// Extract form fields and file info from webhook
const body = $input.first().json;
const headers = $input.first().json.headers || {};

// Build metadata from webhook body fields
const metadata = {
  title: body.title || 'Untitled Document',
  doc_type: body.doc_type || 'manual',
  machine_type: body.machine_type || '',
  category: body.category || '',
  uploaded_by: body.uploaded_by || '',
  original_filename: body.original_filename || '',
  file_path: body.file_path || '',
  mime_type: body.mime_type || '',
};

// Detect file type for routing
let file_type = 'unknown';
if (metadata.mime_type.includes('pdf')) file_type = 'pdf';
else if (metadata.mime_type.includes('image')) file_type = 'image';

return {
  ...metadata,
  file_type,
  ingest_id: Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
};

// Merge parse result with original metadata
const parsed = $input.first().json;
const meta = $('Extract Metadata').first().json;

return {
  ...meta,
  full_text: parsed.full_text || parsed.text || '',
  page_count: parsed.page_count || parsed.pages?.length || 1,
  pages: parsed.pages || [],
  ingest_id: meta.ingest_id,
};

// Split chunk response into individual items for embedding
const result = $input.first().json;
const chunks = result.chunks || [];

// Return each chunk as a separate output item
return chunks.map(chunk => ({
  chunk_index: chunk.chunk_index,
  text: chunk.text,
  char_count: chunk.char_count,
  ingest_id: $('Merge Parse Result').first().json.ingest_id,
  title: $('Merge Parse Result').first().json.title,
  doc_type: $('Merge Parse Result').first().json.doc_type,
  machine_type: $('Merge Parse Result').first().json.machine_type,
  category: $('Merge Parse Result').first().json.category,
  uploaded_by: $('Merge Parse Result').first().json.uploaded_by,
  page_count: $('Merge Parse Result').first().json.page_count,
}));

// Collect all chunk texts for batch embedding
const items = $input.all();
const chunkTexts = items.map(item => item.json.text);

// Batch embed all chunks at once
return {
  texts: chunkTexts,
  item_count: items.length,
  // Preserve original items in the workflow
  ingest_id: items[0]?.json?.ingest_id,
};

// Pair embeddings with their chunk metadata for Qdrant
const embedResult = $input.first().json;
const embeddings = embedResult.embeddings || [];
const chunkItems = $('Prepare Chunk Items').all();

const points = chunkItems.map((item, i) => ({
  id: item.json.ingest_id + '_' + item.json.chunk_index,
  vector: embeddings[i] || [],
  payload: {
    doc_type: item.json.doc_type,
    machine_type: item.json.machine_type,
    category: item.json.category,
    chunk_text: item.json.text,
    chunk_index: item.json.chunk_index,
    source_title: item.json.title,
    uploaded_by: item.json.uploaded_by,
    ingest_id: item.json.ingest_id,
    created_at: new Date().toISOString(),
  }
}));

return {
  points,
  point_count: points.length,
  ingest_id: chunkItems[0]?.json?.ingest_id,
  title: chunkItems[0]?.json?.title,
  doc_type: chunkItems[0]?.json?.doc_type,
  category: chunkItems[0]?.json?.category,
  machine_type: chunkItems[0]?.json?.machine_type,
  uploaded_by: chunkItems[0]?.json?.uploaded_by,
  chunk_details: chunkItems.map(c => ({
    chunk_index: c.json.chunk_index,
    content: c.json.text,
  })),
};

// Build chunk records referencing the document
const docId = $input.first().json.id || $input.first().json.rows?.[0]?.id;
const assemblerData = $('Assemble Qdrant Points').first().json;
const chunks = assemblerData.chunk_details || [];

return chunks.map((chunk, i) => ({
  document_id: docId,
  chunk_index: chunk.chunk_index,
  content: chunk.content,
  qdrant_point_id: assemblerData.ingest_id + '_' + chunk.chunk_index,
}));
